import nodemailer from "nodemailer";
import { lookup } from "dns";
import { promisify } from "util";

const dnsLookup = promisify(lookup);

// Create transporter with custom DNS lookup to force IPv4
const createTransporter = async () => {
  try {
    // Force IPv4 DNS lookup
    const { address } = await dnsLookup(process.env.SMTP_HOST!, { family: 4 });
    console.log(`🔍 Resolved ${process.env.SMTP_HOST} to IPv4: ${address}`);
    
    return nodemailer.createTransport({
      host: address, // Use resolved IPv4 address
      port: Number(process.env.SMTP_PORT) || 587,
      secure: false, // STARTTLS on port 587
      auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS,
      },
      tls: {
        rejectUnauthorized: false, // helps with some shared hosts
      },
      connectionTimeout: 15000,
      greetingTimeout: 10000,
      socketTimeout: 15000,
    });
  } catch (err) {
    console.error("❌ DNS lookup failed, using hostname directly:", err);
    // Fallback to hostname
    return nodemailer.createTransport({
      host: process.env.SMTP_HOST,
      port: Number(process.env.SMTP_PORT) || 587,
      secure: false,
      auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS,
      },
      tls: {
        rejectUnauthorized: false,
      },
    });
  }
};

// --- Send mail function ---
export async function sendMail(to: string, subject: string, html: string, options: { from?: string, cc?: string, bcc?: string } = {}) {
  console.log("🔍 SMTP_FROM =", process.env.SMTP_FROM);
  console.log("🔍 SMTP_USER =", process.env.SMTP_USER);
  if (!to || !subject || !html) {
    throw new Error("Missing required parameters: to, subject, body(html)");
  }

  const fromAddress = options.from || process.env.SMTP_FROM || process.env.SMTP_USER;

  try {
    console.log("🪪 Using from address:", fromAddress);
    
    // Create transporter dynamically to force IPv4
    const transporter = await createTransporter();
    
    const mailOptions: any = {
      from: `"Agent-Lab" <${fromAddress}>`,
      to,
      subject,
      html,
    };
    
    if (options.cc) mailOptions.cc = options.cc;
    if (options.bcc) mailOptions.bcc = options.bcc;
    
    const info = await transporter.sendMail(mailOptions);

    console.log("📧 Email successfully sent!");
    console.log(`   → From: ${fromAddress}`);
    console.log(`   → To: ${to}`);
    console.log(`   → Subject: ${subject}`);
    console.log(`   → Message ID: ${info.messageId}`);
    if (info.response) {
      console.log(`   → Server response: ${info.response}`);
    }

    return info;
  } catch (err) {
    console.error("❌ Failed to send mail:", err);
    throw err;
  }
}
